export function BillingOps({session,lang}:{session:Session;lang:Lang}){
 const {org,error:oe}=useOrg(session),p=useRows('patients',org?.organizationId),invoices=useRows('invoices',org?.organizationId),claims=useRows('insurance_claims',org?.organizationId),payments=useRows('payments',org?.organizationId),[tab,setTab]=useState<'invoices'|'claims'|'payments'>('invoices'),[open,setOpen]=useState(false),[f,setF]=useState<Row>({}),[msg,setMsg]=useState('')
 const [items,setItems]=useState([{description:'Professional services',quantity:1,unit_price:0}])
 function start(){
   setMsg('')
   setItems([{description:'Professional services',quantity:1,unit_price:0}])
   setF(tab==='invoices'?{patient_id:'',invoice_number:'INV-'+Date.now().toString().slice(-7),insurance_amount:0,due_date:''}:tab==='claims'?{patient_id:'',payer_name:'',claim_number:'',billed_amount:0}:{patient_id:'',invoice_id:'',amount:0,payment_method:'card',reference_number:''})
   setOpen(true)
 }
 const invoiceSubtotal=items.reduce((sum,x)=>sum+n(x.quantity)*n(x.unit_price),0)
 const insuranceAmount=n(f.insurance_amount)
 const patientAmount=Math.max(0,invoiceSubtotal-insuranceAmount)
 async function save(e:any){
   e.preventDefault();if(!org||!biller(org.role))return;setMsg('')
   if(tab==='invoices'){
     const valid=items.filter(x=>s(x.description).trim()&&n(x.quantity)>0)
     if(!valid.length){setMsg(lang==='es'?'Agrega al menos una línea válida a la factura.':'Add at least one valid invoice line item.');return}
     if(insuranceAmount>invoiceSubtotal){setMsg(lang==='es'?'El monto del seguro no puede superar el subtotal.':'Insurance amount cannot exceed the subtotal.');return}
     const inv=await supabase.rpc('oculivo_create_invoice',{
       p_organization_id:org.organizationId,
       p_patient_id:f.patient_id,
       p_invoice_number:s(f.invoice_number).trim(),
       p_insurance_amount:insuranceAmount,
       p_due_date:f.due_date||null,
       p_items:valid.map(x=>({description:s(x.description).trim(),quantity:n(x.quantity),unit_price:n(x.unit_price)}))
     })
     if(inv.error){setMsg(inv.error.message);return}
   }else if(tab==='claims'){
     const r=await supabase.from('insurance_claims').insert({organization_id:org.organizationId,patient_id:f.patient_id,claim_number:f.claim_number||null,payer_name:f.payer_name,billed_amount:n(f.billed_amount)})
     if(r.error){setMsg(r.error.message);return}
   }else{
     const r=await supabase.rpc('oculivo_record_payment',{
       p_organization_id:org.organizationId,
       p_patient_id:f.patient_id,
       p_invoice_id:f.invoice_id||null,
       p_amount:n(f.amount),
       p_payment_method:s(f.payment_method),
       p_reference_number:s(f.reference_number)||null
     })
     if(r.error){setMsg(r.error.message);return}
   }
   setOpen(false);await Promise.all([invoices.load(),claims.load(),payments.load()])
 }
 const pn=(id:any)=>{const x=p.rows.find(q=>q.id===id);return x?s(x.first_name)+' '+s(x.last_name):(lang==='es'?'Paciente':'Patient')}
 const rows=tab==='invoices'?invoices.rows:tab==='claims'?claims.rows:payments.rows
 return <><div className="wf-tabs"><button className={tab==='invoices'?'active':''} onClick={()=>setTab('invoices')}>{lang==='es'?'Facturas':'Invoices'}</button><button className={tab==='claims'?'active':''} onClick={()=>setTab('claims')}>{lang==='es'?'Reclamaciones':'Claims'}</button><button className={tab==='payments'?'active':''} onClick={()=>setTab('payments')}>{lang==='es'?'Pagos':'Payments'}</button></div><Head title={tab==='invoices'?(lang==='es'?'Facturas':'Invoices'):tab==='claims'?(lang==='es'?'Reclamaciones':'Claims'):(lang==='es'?'Pagos':'Payments')} sub={org?.organizationName||''} button={tab==='invoices'?(lang==='es'?'Nueva factura':'New invoice'):tab==='claims'?(lang==='es'?'Nueva reclamación':'New claim'):(lang==='es'?'Registrar pago':'Record payment')} onClick={start} disabled={!org||!biller(org.role)}/><Alert text={oe||invoices.error||claims.error||payments.error||msg}/>{!(tab==='invoices'?invoices.loading:tab==='claims'?claims.loading:payments.loading)&&!rows.length&&<EmptyState lang={lang} label={tab==='invoices'?(lang==='es'?'facturas':'Invoices'):tab==='claims'?(lang==='es'?'reclamaciones':'Claims'):(lang==='es'?'pagos':'Payments')}/>}<div className="wf-list">{rows.map(r=><article className="wf-row" key={r.id}><div className="wf-grow"><h3>{tab==='invoices'?s(r.invoice_number):tab==='claims'?(s(r.claim_number)||s(r.payer_name)):pn(r.patient_id)}</h3><p>{pn(r.patient_id)+' · $'+Number(tab==='invoices'?r.patient_amount:tab==='claims'?r.billed_amount:r.amount||0).toFixed(2)}{tab==='invoices'?' · '+(lang==='es'?'Pagado $':'Paid $')+Number(r.amount_paid||0).toFixed(2):''}</p></div>{r.status&&<span className="status-badge">{localized(r.status,lang)}</span>}</article>)}</div>{open&&<Modal title={tab==='invoices'?(lang==='es'?'Nueva factura':'New invoice'):tab==='claims'?(lang==='es'?'Nueva reclamación de seguro':'New insurance claim'):(lang==='es'?'Registrar pago':'Record payment')} onClose={()=>setOpen(false)}><form className="wf-form" onSubmit={save}><Field label={lang==='es'?'Paciente':'Patient'}><PatientSelect value={s(f.patient_id)} setValue={v=>setF({...f,patient_id:v})} rows={p.rows} lang={lang}/></Field>{tab==='invoices'?<><Field label={lang==='es'?'Número de factura':'Invoice number'}><input required value={s(f.invoice_number)} onChange={e=>setF({...f,invoice_number:e.target.value})}/></Field><div className="invoice-lines"><div className="invoice-lines-head"><strong>{lang==='es'?'Líneas de factura':'Invoice lines'}</strong><button type="button" onClick={()=>setItems(v=>[...v,{description:'',quantity:1,unit_price:0}])}><Plus size={13}/>{lang==='es'?'Agregar línea':'Add line'}</button></div>{items.map((x,i)=><div className="invoice-line" key={i}><input placeholder={lang==='es'?'Descripción':'Description'} required value={x.description} onChange={e=>setItems(v=>v.map((q,j)=>j===i?{...q,description:e.target.value}:q))}/><input aria-label={lang==='es'?'Cantidad':'Quantity'} type="number" min="0.01" step="0.01" value={x.quantity} onChange={e=>setItems(v=>v.map((q,j)=>j===i?{...q,quantity:n(e.target.value)}:q))}/><input aria-label={lang==='es'?'Precio unitario':'Unit price'} type="number" min="0" step="0.01" value={x.unit_price} onChange={e=>setItems(v=>v.map((q,j)=>j===i?{...q,unit_price:n(e.target.value)}:q))}/><b>{'$'+(n(x.quantity)*n(x.unit_price)).toFixed(2)}</b><button type="button" disabled={items.length===1} onClick={()=>setItems(v=>v.filter((_,j)=>j!==i))}><Trash2 size={13}/></button></div>)}</div><div className="invoice-summary"><span>{lang==='es'?'Subtotal':'Subtotal'}<b>{'$'+invoiceSubtotal.toFixed(2)}</b></span><span>{lang==='es'?'Seguro':'Insurance'}<input type="number" min="0" step="0.01" value={s(f.insurance_amount)} onChange={e=>setF({...f,insurance_amount:e.target.value})}/></span><span>{lang==='es'?'Responsabilidad del paciente':'Patient responsibility'}<b>{'$'+patientAmount.toFixed(2)}</b></span></div><Field label={lang==='es'?'Fecha de vencimiento':'Due date'}><input type="date" value={s(f.due_date)} onChange={e=>setF({...f,due_date:e.target.value})}/></Field></>:tab==='claims'?<><div className="wf-two"><Field label={lang==='es'?'Aseguradora':'Payer name'}><input required value={s(f.payer_name)} onChange={e=>setF({...f,payer_name:e.target.value})}/></Field><Field label={lang==='es'?'Número de reclamación':'Claim number'}><input value={s(f.claim_number)} onChange={e=>setF({...f,claim_number:e.target.value})}/></Field></div><Field label={lang==='es'?'Monto facturado':'Billed amount'}><input type="number" min="0" step="0.01" value={s(f.billed_amount)} onChange={e=>setF({...f,billed_amount:e.target.value})}/></Field></>:<><Field label={lang==='es'?'Factura':'Invoice'}><select value={s(f.invoice_id)} onChange={e=>setF({...f,invoice_id:e.target.value})}><option value="">{lang==='es'?'Sin factura':'No invoice'}</option>{invoices.rows.filter(i=>i.patient_id===f.patient_id).map(i=><option key={i.id} value={i.id}>{i.invoice_number}</option>)}</select></Field><div className="wf-two"><Field label={lang==='es'?'Monto':'Amount'}><input required type="number" min="0.01" step="0.01" value={s(f.amount)} onChange={e=>setF({...f,amount:e.target.value})}/></Field><Field label={lang==='es'?'Método de pago':'Payment method'}><select required value={s(f.payment_method)} onChange={e=>setF({...f,payment_method:e.target.value})}><option value="card">{lang==='es'?'Tarjeta':'Card'}</option><option value="cash">{lang==='es'?'Efectivo':'Cash'}</option><option value="check">{lang==='es'?'Cheque':'Check'}</option><option value="ach">ACH</option><option value="other">{lang==='es'?'Otro':'Other'}</option></select></Field></div><Field label={lang==='es'?'Referencia':'Reference'}><input value={s(f.reference_number)} onChange={e=>setF({...f,reference_number:e.target.value})}/></Field></>}{msg&&<Alert text={msg}/>}<button type="submit" className="wf-primary full"><Save size={15}/>{lang==='es'?'Guardar':'Save'}</button></form></Modal>}</>
}

export function DocumentsOps({session,lang}:{session:Session;lang:Lang}){
 const {org,error:oe}=useOrg(session),d=useRows('documents',org?.organizationId),p=useRows('patients',org?.organizationId),[open,setOpen]=useState(false),[file,setFile]=useState<File|null>(null),[patientId,setPatientId]=useState(''),[docType,setDocType]=useState('general'),[description,setDescription]=useState(''),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false)
 async function upload(e:any){e.preventDefault();if(!org||!file||!documentWriter(org.role))return;setBusy(true);setMsg('');const allowed=new Set(['application/pdf','image/png','image/jpeg','image/webp','image/heic','image/heif']);if(file.size>25*1024*1024){setMsg(lang==='es'?'El archivo supera el límite de 25 MB.':'File exceeds the 25 MB limit.');setBusy(false);return}if(file.type&&!allowed.has(file.type)){setMsg(lang==='es'?'Ese tipo de archivo no está permitido.':'That file type is not allowed.');setBusy(false);return}const safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,'-');const path=org.organizationId+'/'+(patientId||'practice')+'/'+Date.now()+'-'+safe;const up=await supabase.storage.from('oculivo-documents').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(up.error){setMsg(up.error.message);setBusy(false);return}const row=await supabase.from('documents').insert({organization_id:org.organizationId,patient_id:patientId||null,uploaded_by:session.user.id,document_type:docType||'general',file_name:file.name,storage_path:path,mime_type:file.type||null,file_size:file.size,description:description||null});if(row.error){await supabase.storage.from('oculivo-documents').remove([path]);setMsg(row.error.message)}else{setOpen(false);setFile(null);setPatientId('');setDescription('');await d.load()}setBusy(false)}
 async function view(r:Row){const q=await supabase.storage.from('oculivo-documents').createSignedUrl(s(r.storage_path),300);if(q.error){setMsg(q.error.message);return}window.open(q.data.signedUrl,'_blank','noopener,noreferrer')}
 async function remove(r:Row){if(!org||!documentDeleter(org.role)||!confirm(lang==='es'?'¿Eliminar este documento?':'Delete this document?'))return;setMsg('');const q=await supabase.from('documents').delete().eq('id',r.id).eq('organization_id',org.organizationId);if(q.error){setMsg(q.error.message);return}const rm=await supabase.storage.from('oculivo-documents').remove([s(r.storage_path)]);if(rm.error)setMsg(lang==='es'?'Se eliminó el registro, pero el archivo requiere limpieza de almacenamiento.':'Record deleted; storage object requires cleanup.');await d.load()}
 const pn=(id:any)=>{const x=p.rows.find(q=>q.id===id);return x?s(x.first_name)+' '+s(x.last_name):(lang==='es'?'Consultorio':'Practice')}
 return <><Head title={lang==='es'?'Documentos':'Documents'} sub={org?.organizationName||''} button={lang==='es'?'Subir documento':'Upload document'} onClick={()=>{setOpen(true);setMsg('')}} disabled={!org||!documentWriter(org.role)}/><Alert text={oe||d.error||msg}/>{!d.loading&&!d.rows.length&&<EmptyState lang={lang} label={lang==='es'?'documentos':'Documents'}/>}<div className="wf-list">{d.rows.map(r=><article className="wf-row" key={r.id}><div className="wf-grow"><h3>{s(r.file_name)}</h3><p>{pn(r.patient_id)+' · '+s(r.document_type)+(r.file_size?' · '+Math.max(1,Math.round(Number(r.file_size)/1024))+' KB':'')}</p></div><button onClick={()=>void view(r)}>{lang==='es'?'Abrir':'Open'}</button>{org&&documentDeleter(org.role)&&<button className="icon-danger" onClick={()=>void remove(r)}><Trash2 size={14}/></button>}</article>)}</div>{open&&<Modal title={lang==='es'?'Subir documento':'Upload document'} onClose={()=>setOpen(false)}><form className="wf-form" onSubmit={upload}><Field label={lang==='es'?'Paciente opcional':'Patient (optional)'}><select value={patientId} onChange={e=>setPatientId(e.target.value)}><option value="">{lang==='es'?'Documento del consultorio':'Practice document'}</option>{p.rows.map(x=><option key={x.id} value={x.id}>{s(x.first_name)+' '+s(x.last_name)}</option>)}</select></Field><Field label={lang==='es'?'Tipo de documento':'Document type'}><select value={docType} onChange={e=>setDocType(e.target.value)}><option value="general">General</option><option value="clinical">{lang==='es'?'Clínico':'Clinical'}</option><option value="insurance">{lang==='es'?'Seguro':'Insurance'}</option><option value="consent">{lang==='es'?'Consentimiento':'Consent'}</option><option value="prescription">{lang==='es'?'Receta':'Prescription'}</option><option value="billing">{lang==='es'?'Facturación':'Billing'}</option></select></Field><Field label={lang==='es'?'Archivo':'File'}><input type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.heic,.heif" required onChange={e=>setFile(e.target.files?.[0]||null)}/></Field><Field label={lang==='es'?'Descripción':'Description'}><textarea rows={3} value={description} onChange={e=>setDescription(e.target.value)}/></Field>{msg&&<Alert text={msg}/>}<button type="submit" className="wf-primary full" disabled={busy||!file}><Save size={15}/>{busy?(lang==='es'?'Subiendo…':'Uploading…'):(lang==='es'?'Subir':'Upload')}</button></form></Modal>}</>
}
